import { Button, Collapse, List, Menu, Modal, Typography } from "@arco-design/web-react";
import { SchemaTable } from '@/components/schema';
import { useMemo, useState } from "react";
import { schemaToList, schemaToTypeScript, schemaToJSON } from "@/utils/schema";
import Hljs from "@/components/custom/Hljs";


interface TableDetailProps extends React.HTMLProps<HTMLDivElement>{
    o: any
}
export default ({
    o,
    ...props
}: TableDetailProps) => {

    const [visible, setVisible] = useState<boolean>(false);

    const schema = useMemo(() => {
        let schema: JSONSchema = {
            type: 'object',
            properties: {}
        }
        for (const item of o.column) {
            schema.properties[item.key] = {
                type: item.type,
                format: item.format,
                title: item.desc,
                enum: item.enum,
                maxLength: item.length,
                default: item.default
            }
        }
        return schema;
    },[])

    const json = useMemo(()=> {
        return schemaToJSON(schema)
    }, [schema])

    const tsText = useMemo(() => {
        return schemaToTypeScript(schema)
    },[schema])

    return (
        <div {...props}>
            <div className={'items-center-between'}>
            <Typography.Title heading={6} >{o.desc}({props.id})</Typography.Title>
            <Button type="primary" style={{ marginBottom: 16 }}
                onClick={() => setVisible(true)}
            >
                查看详情
            </Button>
            </div>
            <SchemaTable
                data={o.column}
                pagination={false}
                schema={{
                    "type": "object",
                    "properties": {
                        "key": {
                            "type": "string",
                            "default": "id",
                            "title": "字段名称"
                        },
                        "type": {
                            "type": "string",
                            "default": "integer",
                            "title": "字段类型"
                        },
                        "length": {
                            "type": "integer",
                            "default": 11,
                            "title": "字段长度"
                        },
                        "desc": {
                            "type": "string",
                            "default": "用户I23D2323",
                            "title": "备注"
                        },
                    }
                }}
            />
            <Modal
                title={o.desc}
                visible={visible}
                style={{ width: 900 }}
                onCancel={() => setVisible(false)}
            >
                    <Collapse
                        defaultActiveKey={['1', '3']}
                    >
                        <Collapse.Item header='字段列表' name='1'>
                            <Hljs>
                                {JSON.stringify(o.column.map((o) => o.key))}
                            </Hljs>
                        </Collapse.Item>
                        {/* <Collapse.Item header='数据表对应 JSON' name='2'>
                            <Hljs>
                                {JSON.stringify(json, null, '\t')}
                            </Hljs>
                        </Collapse.Item> */}
                        <Collapse.Item header='数据表对应 JSONSchemal' name='3'>
                            <Hljs>
                                {JSON.stringify(schema, null, '\t')}
                            </Hljs>
                        </Collapse.Item>
                        <Collapse.Item header='数据表对应 TypeScript' name='4'>
                            <Hljs code="TypeScript">
                                {tsText}
                            </Hljs>
                        </Collapse.Item>
                    </Collapse>
            </Modal>
        </div>
    )
}